} else {
  // Product-level snapshot upsert — variant is NULL, so use a manual upsert
  const [existingSnap] = await sql<{ id: string }[]>`
    SELECT id FROM dashboard_snapshots
    WHERE product_external_id = ${productIdRaw}::bigint
    AND variant_external_id IS NULL
    LIMIT 1
  `;
  if (existingSnap) {
    await sql`
      UPDATE dashboard_snapshots
      SET active_waitlist_count = active_waitlist_count + 1,
          total_signups = total_signups + 1,
          item_display_name = ${safeDisplayName},
          snapshot_updated_at = now()
      WHERE id = ${existingSnap.id}
    `;
  } else {
    await sql`
      INSERT INTO dashboard_snapshots (
        product_external_id, variant_external_id, item_display_name,
        active_waitlist_count, total_signups, total_notified, total_conversions,
        snapshot_updated_at
      ) VALUES (
        ${productIdRaw}::bigint, NULL, ${safeDisplayName},
        1, 1, 0, 0, now()
      )
    `;
  }
}
